// geschlossen -> 11 offen, 00 und 11 identisch = Loop-Punkt) als echtes
// Overlay auf #augen-blink ab. Zeitlinie woertlich aus der Messung: die
// Frames 00-08 SCHLIESSEN (deshalb 9 kurze Schritte), 09-11 OEFFNEN (3
// laengere) -- ein echtes Lid faellt schnell und geht langsamer auf.
// Gesamt ~300-340ms (Gabriels Vorgabe 250-350ms).
// ⚠️ Galton-Watson-Regel UNVERAENDERT (siehe LECK-FIX oben): EINE
// Selbstartende-Kette, der Doppelschlag bleibt ein einmaliger Bonus ohne
// eigene Fortpflanzung (zeitplanNeu=false). blinzelAbspielen() ist eine
// ENDLICHE Kette -- sie erzeugt nie eine neue Kette, sie liefert nur an
// blinzelWeiterPlanen() zurueck. Blinzeln bleibt unabhaengig von der
// Gesichtserkennung (das Lid braucht kein Signal); nur #pupillen-glow
// bleibt erkennungs-gekoppelt. Läuft NICHT ueber einem Sonderausdruck
// (dessen Frames tragen ihre eigenen Augen).
function blinzeln(zeitplanNeu = true){
  if(_sonderLaeuft){
    if(zeitplanNeu) blinzelWeiterPlanen(); // Kette haelt, kein zweiter Strang
    return;
  }
  const schritte = [];
  for(let f = 0; f <= 8; f++) schritte.push([f, blinzelDauerSchliessen(), f < 7 ? "halb1" : "zu"]);
  schritte.push([8, blinzelDauerGeschlossenHalten(), "zu"]);
  for(let f = 9; f <= 11; f++) schritte.push([f, blinzelDauerOeffnen(), "halb2"]);
  blinzelAbspielen(schritte, 0, zeitplanNeu);
}
function blinzelAbspielen(schritte, idx, zeitplanNeu){
  if(idx >= schritte.length){
    $("augen-blink").style.opacity = "0";
    blinzelPhase = null; gesichtNeuZeichnen(false);
    if(zeitplanNeu){
      if(Math.random() < 0.12){ setTimeout(() => blinzeln(false), 120 + Math.random()*80); }
      blinzelWeiterPlanen();
    }
    return;
  }
  const [frame, dauer, phase] = schritte[idx];
  $("augen-blink").src = BLINK_BILDER[frame];
  $("augen-blink").style.opacity = "1";
  blinzelPhase = phase; gesichtNeuZeichnen(false);
  setTimeout(() => blinzelAbspielen(schritte, idx + 1, zeitplanNeu), dauer);
}
function blinzelWeiterPlanen(){
  setTimeout(() => blinzeln(true), 2000 + Math.random()*5000); // 2-7s, unregelmaessig (Gabriels Vorgabe)
}
blinzelWeiterPlanen();

